// This file is generated by AI.

// 「观察某组取值是否变化」的工具 —— **Svelte 5 响应式版, 零轮询**。
//
// `watchValues` 替代 zustand `subscribe` 的第二参 `previous` (Svelte 的订阅不给 previous):
// 需要"只在某个字段变化时才做事"的调用点 (编辑器设置 / 诊断 / git / 预览同步、差异显示方式) 用它。
//
// 实现用 `$effect.root` + `$effect`: `select()` 在 effect 体内读, Svelte 自动把读到的 `$state`
// 记成依赖 —— **只有真正被写过的字段**才唤醒这个 effect, 没有定时器、没有轮询, 唤醒同步于状态
// 变化。做法与 `store.svelte.ts` 的 `ensureStateChannel` 同一套路。`.svelte.ts` 后缀是必须的:
// rune 只能在 svelte 模块里用。
//
// 两条使用约定 (写反了不报错, 只是静默失效):
//   1. `select()` 里**不要**用 `untrack()` —— 那会切断依赖, 这个观察者再也不会被唤醒;
//   2. `onChange()` 里读什么都不算依赖 (内部用 `untrack` 包住), 因此它就算写 store 也不会自激。

import { untrack } from 'svelte';

export interface Watcher {
  /** 停止观察 */
  stop(): void;
}

export interface WatchOptions {
  /** 取值: 返回要在意的那些字段 (建议返回数组, 顺序固定)。读到的 `$state` 会成为依赖。 */
  select: () => readonly unknown[];
  /** 变化时回调 (首次订阅**不会**调用 —— 由调用方自己定基线, 见 `watchValues`) */
  onChange: () => void;
}

/**
 * 取值的"变了没有"判据: 长度相同且逐项 `Object.is`。
 *
 * 单独导出是因为**这一条才是可以单测的不变量** —— 观察者的 effect 部分依赖 Svelte 运行时,
 * 而 vitest 跑在 SSR 模式 (`generate: 'server'`), 那里的 rune 是惰性的 (`$effect` 不会执行),
 * 因此 effect 相关的行为一律靠浏览器实机验证。
 */
export function valuesEqual(next: readonly unknown[], previous: readonly unknown[]): boolean {
  if (next.length !== previous.length) return false;
  for (let index = 0; index < next.length; index += 1) {
    if (!Object.is(next[index], previous[index])) return false;
  }
  return true;
}

/**
 * 观察一组取值, 变化时回调。
 *
 * 返回的对象只有 `stop()` —— 调用方负责在合适的时机停掉 (组件销毁、项目关闭)。
 */
export function watchValues(options: WatchOptions): Watcher {
  const { select, onChange } = options;

  // 初次取值在 effect 之外: 它只用来确定基线, 不该建立依赖。
  let previous = [...select()];
  let stopped = false;

  const disposeRoot = $effect.root(() => {
    $effect(() => {
      const next = select();
      if (stopped) return;
      if (valuesEqual(next, previous)) return;

      previous = [...next];
      // `onChange` 里读到的状态不算依赖: 依赖只应来自 `select`, 否则回调自己会把
      // 观察者再唤醒一次 (例如回调里顺手读了别的字段)。
      untrack(onChange);
    });
  });

  return {
    stop() {
      stopped = true;
      disposeRoot();
    },
  };
}
